func entity(for id: String) -> Entity {
    if let hit = cache.object(forKey: id as NSString) { return hit }   // cache hit
    let loaded = source.load(id)                                       // source of truth
    cache.setObject(loaded, forKey: id as NSString, cost: loaded.size)
    return loaded
}

func update(_ e: Entity) { source.save(e); cache.removeObject(forKey: e.id as NSString) }

