actor EntityCache {
    private var entries: [String: Entry] = [:]        // value + deadline
    private var inflight: [String: Task<Entity, Error>] = [:]

    func entity(for id: String,
                load: @Sendable @escaping (String) async throws -> Entity) async throws -> Entity {
        if let e = entries[id], !e.expired { return e.value }
        if let t = inflight[id] { return try await t.value }   // share one load
        let task = Task { try await load(id) }
        inflight[id] = task
        defer { inflight[id] = nil }
        let value = try await task.value
        entries[id] = Entry(value: value, deadline: .now + ttl)
        return value
    }
}
